=Aquí tienes la información cruda para procesar:

=== FUENTE 1: PEDIDO (Puede venir como JSON string) ===
{{ JSON.stringify($('Pedido').item.json) }}

=== FUENTE 2: EDIT FIELDS (Datos maestros) ===
{{ JSON.stringify($('Edit Fields').item.json) }}

=== FUENTE 3: DATOS (Texto desordenado o arrays) ===
{{ JSON.stringify($('datos').item.json) }}

parameters.jsCode:
return $input.all().map(item => {
  // 1. Identificamos el objeto que contiene tus datos
  const datosInternos = item.json.query;

  let resultado = {};

  // 2. Lógica de procesamiento
  if (typeof datosInternos === 'object' && datosInternos !== null) {
    // CASO A: Ya es un objeto, lo usamos directamente
    resultado = datosInternos;
  } else if (typeof datosInternos === 'string') {
    // CASO B: Es texto (string)
    try {
      // Intento 1: ¿Es un JSON válido? (Ej: '{"id": 123}')
      resultado = JSON.parse(datosInternos);
    } catch (e) {
      // Intento 2: No es JSON válido, es texto plano (Ej: 'id: 123, pais: Peru')
      // Limpiamos llaves {} si existen y separamos por comas
      const textoLimpio = datosInternos.replace(/^{|}$/g, ''); 
      const pares = textoLimpio.split(',');

      pares.forEach(par => {
        // Separamos por el primer ':' que encontremos
        const [clave, ...restoValor] = par.split(':');

        if (clave && restoValor.length > 0) {
          // Limpiamos espacios en blanco alrededor
          const key = clave.trim();
          // Unimos el resto por si el valor contenía ':' (ej: una url o fecha)
          const value = restoValor.join(':').trim();

          resultado[key] = value;
        }
      });
    }
  }

  // 3. Devolvemos los datos limpios
  return {
    json: resultado
  };
});

// Toma el input del nodo anterior
const raw = $input.first().json;

// Si el dato viene como string (ej: desde AI Agent), parsearlo
let input = raw;
if (typeof raw.output === "string") {
  try {
    input = JSON.parse(raw.output);
  } catch (e) {
    // Si no es JSON válido, intentar con el objeto directo
    input = raw;
  }
} else if (typeof raw.output === "object" && raw.output !== null) {
  input = raw.output;
}

// === VALIDACIÓN: Detectar JSON de error del AI Agent ===
if (input.error === "DATOS_INSUFICIENTES") {
  throw new Error(`AI Agent no pudo construir el JSON: ${input.message}`);
}

// === VALIDACIÓN CRÍTICA: topup_amount no puede ser 0 ni inválido ===
const topupRaw = Number(input.topup_amount);
if (!topupRaw || topupRaw <= 0 || isNaN(topupRaw)) {
  throw new Error(
    `topup_amount inválido: "${input.topup_amount}". ` +
    `El AI Agent no determinó el monto correctamente. ` +
    `purchase_type="${input.purchase_type}", plan_type="${input.plan_type}"`
  );
}

// Transformar campos al tipo correcto
const output = {
  customer_id: Number(input.customer_id) || null,
  purchase_source: input.purchase_source || null,
  purchase_type: input.purchase_type || null,
  plan_type: input.plan_type || null,
  topup_amount: topupRaw,
  cashback_amount: Number(input.cashback_amount) || 0,
  country: input.country
    ? input.country.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    : null,
  coupon: input.coupon || null,
  transaction_code: input.transaction_code || null,
  description: input.description || null,
};

return [{ json: output }];

